/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountTileFlipWave, type TileFlipWaveOptions } from "../../components/tile-flip-wave/TileFlipWaveEngine.js";
import type { MotionController } from "../../components/tile-flip-wave/motion-runtime";

export function TileFlipWave(props: { options?: TileFlipWaveOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountTileFlipWave(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="tile-flip-wave" />;
}

